import type { Cart } from "./types";

/** A shopper signed in: the saved cart and this device's cart merge, each item once, the larger quantity kept. */
export function cartOnSignIn(device: Cart, saved: Cart | null): Cart {
  if (!saved) return device;
  const bySku = new Map(saved.items.map((i) => [i.sku, { ...i }]));
  for (const i of device.items) {
    const have = bySku.get(i.sku);
    bySku.set(i.sku, have ? { ...have, qty: Math.max(have.qty, i.qty) } : { ...i });
  }
  return { ...saved, items: [...bySku.values()] };
}

