export async function afterSignIn(session: Session) {
  const saved = await loadSavedCart(session.user);
  session.cart = cartOnSignIn(session.cart, saved);
  // The wishlist shares the cart's merge now, so a second device never drops either.
  session.wishlist = listOnSignIn(session.wishlist, await loadSavedList(session.user));
  await saveCart(session.user, session.cart);
