import type { List } from "./types";
import { cartOnSignIn } from "../cart/merge";

/** A shopper signed in: the wishlist merges the way the cart does. */
export function listOnSignIn(device: List, saved: List | null): List {
  return cartOnSignIn(device as any, saved as any) as any;
}

import { expect, test } from "bun:test";
import { cartOnSignIn } from "../../src/cart/merge";

test("cart merges on a second sign-in", () => {
  const saved = { items: [{ sku: "mug", price: 24, qty: 1 }, { sku: "tea", price: 9, qty: 2 }] };
  const device = { items: [{ sku: "lamp", price: 40, qty: 1 }] };
  expect(cartOnSignIn(device, saved).items.map((i) => i.sku).sort()).toEqual(["lamp", "mug", "tea"]);
});
